-- Baseline auth schema (canonical fixture — see ../README.md).
-- Idempotent: safe to run repeatedly. Owns ONLY the universal auth tables
-- (users + sessions) that every product needs identically. Product-specific
-- ownership links (associating a pre-signup result with a user) are added by the
-- product-auth workflow as a LATER migration — do not edit this file for those.

-- users: normalized-unique email + optional password hash.
create table if not exists users (
  id            uuid primary key default gen_random_uuid(),
  email         text not null,
  password_hash text,                          -- null allowed for OAuth/passwordless identities
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- Case-insensitive email uniqueness. Insert the email as typed; the index
-- normalizes. (Do not also add a plain unique(email) — that would be redundant
-- and reject only exact-case dupes.)
create unique index if not exists users_email_lower_key on users (lower(email));

-- sessions: opaque server-side sessions, revocable, with explicit expiry.
create table if not exists sessions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references users(id) on delete cascade,
  token_hash  text not null,                   -- store a HASH of the opaque token, never the token itself
  expires_at  timestamptz not null,
  created_at  timestamptz not null default now(),
  revoked_at  timestamptz                       -- non-null => revoked; check alongside expiry on every request
);

create unique index if not exists sessions_token_hash_key on sessions (token_hash);
create index if not exists sessions_user_id_idx on sessions (user_id);
create index if not exists sessions_expires_at_idx on sessions (expires_at);
